def guarded(user_input, retrieved):
    if inject_clf(user_input) > 0.8:        # input guardrail: injection
        return REFUSAL
    prompt = redact_pii(user_input)         # never send raw PII downstream
    out = model.generate(prompt, retrieved)
    try:
        data = validate_schema(out)         # output guardrail: contract
    except SchemaError:
        return escalate()                   # fail closed, not fail open
    if not all(c.source in retrieved for c in data.claims):
        return escalate()                   # grounding check: no citation, no answer
    return data

