# expense_router.py — the right system: rules first, one model call for the tail
CATEGORY_RULES = {           # deterministic majority, zero model cost
    r"UBER|LYFT|TAXI":  "travel",
    r"AWS|GCP|AZURE":   "cloud",
    r"DELTA|UNITED":    "airfare",
}
def categorize(receipt):
    for pattern, cat in CATEGORY_RULES.items():
        if re.search(pattern, receipt.merchant, re.I):
            return cat                        # most receipts resolved here, no LLM
    return classify_llm(receipt, CATEGORIES)  # one call for the ambiguous tail
